import html, json, webbrowser
from pathlib import Path
from datetime import datetime, timezone
from .brand import logo_svg, BRAND_NAME, BRAND_TAGLINE
from .visuals import relationship_svg, timeline_svg


def esc(v):return html.escape('' if v is None else str(v))
def _rows(data):
    if data is None:return []
    if isinstance(data,list):return [x for x in data if isinstance(x,dict)]
    if isinstance(data,dict):return [{'key':k,'value':v} for k,v in data.items()]
    return []
def _table(rows,columns=None,table_id='',empty='Sem dados para esta seção.'):
    rows=_rows(rows)
    if not rows:return f'<div class="empty">{esc(empty)}</div>'
    columns=columns or list(dict.fromkeys(k for r in rows for k in r.keys()))
    head=''.join(f'<th>{esc(c.replace("_"," ").title())}</th>' for c in columns)
    body=[]
    for r in rows:
        cells=[]
        for c in columns:
            v=r.get(c,'')
            if isinstance(v,(list,dict)):v=json.dumps(v,ensure_ascii=False,default=str)
            cells.append(f'<td>{esc(v)}</td>')
        body.append('<tr>'+''.join(cells)+'</tr>')
    return f'<div class="table-wrap"><table id="{esc(table_id)}"><thead><tr>{head}</tr></thead><tbody>{"".join(body)}</tbody></table></div>'
def _metric(label,value,note=''):return f'<div class="metric"><span>{esc(label)}</span><strong>{esc(value)}</strong><small>{esc(note)}</small></div>'
def _pill(text,tone='neutral'):return f'<span class="pill {esc(tone)}">{esc(text)}</span>'
def _tone(band):return {'HIGH':'danger','MODERATE':'warn','LOW':'info'}.get(str(band or '').upper(),'neutral')
def _bar(value):
    try:v=max(0,min(1,float(value)))
    except Exception:v=0
    return f'<div class="bar"><i style="width:{v*100:.1f}%"></i></div>'
def _confidence_cards(confidence):
    parts=[]
    for name,v in (confidence or {}).items():
        score=float((v.get('score',0) if isinstance(v,dict) else v) or 0);band=v.get('band','') if isinstance(v,dict) else ''
        parts.append(f'<div class="confidence-card"><div><span>{esc(name.replace("_"," ").title())}</span>{_pill(band,_tone(band))}</div><strong>{score:.2f}</strong>{_bar(score)}</div>')
    return ''.join(parts) or '<div class="empty">Sem matriz de confiança.</div>'
def _ioc_decisions(rows):
    cleaned=[{'ioc':x.get('ioc'),'type':x.get('ioc_type'),'confidence':x.get('confidence'),'actionability':x.get('actionability'),'active':x.get('active_now'),'fp_risk':x.get('false_positive_risk'),'decision':x.get('decision'),'block':x.get('block_recommended'),'hunt':x.get('hunt_recommended')} for x in (rows or [])]
    return _table(cleaned,['ioc','type','confidence','actionability','active','fp_risk','decision','block','hunt'],'ioc-table')

def build_report(data,output_path,title=None):
    output_path=Path(output_path);output_path.parent.mkdir(parents=True,exist_ok=True)
    meta=data.get('meta',{});brief=data.get('executive_brief',{});assessment=brief.get('executive_assessment',data.get('executive_assessment',{}))
    actions=data.get('action_matrix',[]);iocs=data.get('ioc_decisions',[]);gaps=data.get('collection_gaps',[]);pivots=data.get('next_best_pivots',[]);confidence=data.get('confidence',{})
    victimology=data.get('victimology',{});objectives=data.get('objectives',{});lifecycle=data.get('lifecycle',{});attribution=data.get('attribution_assessments',[]);clusters=data.get('campaign_clusters',[])
    evidence=data.get('evidence_ledger',[]);source_status=data.get('source_status',[]);detection=data.get('detection_package',{});ownership=data.get('ownership',{})
    similarity=data.get('domain_similarity',[]);durable=data.get('durable_identifiers',[]);negative=data.get('negative_evidence',[]);source_ind=data.get('source_independence',[]);churn=data.get('infrastructure_churn',{})
    takeover=data.get('takeover_exposure',[]);timeline=data.get('timeline',[]);graph=data.get('relationship_graph',{});provider_plan=data.get('provider_plan',[]);feature_matrix=data.get('feature_matrix',[])
    ai_entities=data.get('ai_entities',[]);ai_analysis=data.get('ai_analysis',{});ai_metadata=data.get('ai_metadata',{})
    case_id=meta.get('case_id') or 'CASE';analyst=meta.get('analyst') or 'não informado';generated=meta.get('generated_at') or datetime.now(timezone.utc).isoformat();title=title or f'{BRAND_NAME} · {case_id}'
    block_n=sum(1 for x in iocs if x.get('block_recommended'));hunt_n=sum(1 for x in iocs if x.get('hunt_recommended'));p1_n=sum(1 for x in actions if x.get('priority')=='P1');high_attr=sum(1 for x in attribution if str(x.get('common_operator_confidence','')).upper()=='HIGH')
    nav=[('overview','Overview'),('actions','Ações'),('iocs','IOCs'),('relationships','Relações'),('similarity','Similaridade'),('campaign','Campanha'),('attribution','Atribuição'),('ai','AI Assist'),('collection','Coleta'),('detection','Detecção'),('evidence','Evidências'),('sources','Fontes'),('exports','Export')]
    embedded=json.dumps(data,ensure_ascii=False,default=str).replace('</','<\\/')
    judgment=assessment.get('judgment','') if isinstance(assessment,dict) else str(assessment);implication=assessment.get('implication','') if isinstance(assessment,dict) else ''
    ownership_rows=[{'domain':k,**(v if isinstance(v,dict) else {'value':v})} for k,v in ownership.items()]
    css="""
:root{--bg:#f5f6f7;--panel:#fff;--ink:#101214;--muted:#68707a;--line:#dfe3e7;--soft:#eef1f3;--radius:16px;--shadow:0 8px 28px rgba(0,0,0,.055)}[data-theme=dark]{--bg:#0d0f11;--panel:#14171a;--ink:#f3f4f5;--muted:#9aa1a9;--line:#292e33;--soft:#1d2125;--shadow:none}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}.shell{max-width:1580px;margin:auto;padding:0 24px 60px}.topbar{position:sticky;top:0;z-index:10;background:var(--bg);border-bottom:1px solid var(--line);margin:0 -24px;padding:12px 24px;display:flex;align-items:center;gap:16px}.brand{display:flex;align-items:center;gap:11px;min-width:max-content}.brand small{display:block;color:var(--muted);font-size:11px}.nav{display:flex;gap:3px;overflow:auto;white-space:nowrap;flex:1}.nav a{text-decoration:none;color:var(--muted);padding:7px 8px;border-radius:8px;font-size:12px}.nav a:hover{background:var(--soft);color:var(--ink)}.btn{border:1px solid var(--line);background:var(--panel);color:var(--ink);padding:8px 11px;border-radius:9px;cursor:pointer}.hero{padding:48px 0 26px;display:grid;grid-template-columns:1.4fr 1fr;gap:24px;align-items:end}.eyebrow{font:600 11px/1.2 ui-monospace,monospace;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}h1{font-size:42px;line-height:1.08;margin:10px 0 14px;letter-spacing:-.035em}.lede{font-size:17px;color:var(--muted)}.hero-meta{display:grid;grid-template-columns:1fr 1fr;gap:10px}.metric,.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.metric{padding:14px}.metric span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.metric strong{font-size:25px;display:block;margin-top:7px}.metric small{color:var(--muted)}section{scroll-margin-top:78px;margin-top:30px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:11px}.section-head p{color:var(--muted);margin:0;max-width:700px}h2{margin:0;font-size:23px}.grid{display:grid;gap:12px}.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.card{padding:17px}.card h3{margin:0 0 11px;font-size:15px}.judgment{font-size:21px;line-height:1.45}.muted{color:var(--muted)}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:3px 8px;font-size:11px;font-weight:650}.pill.danger{background:var(--ink);color:var(--bg);border-color:var(--ink)}.pill.warn,.pill.info{background:var(--soft)}.confidence-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.confidence-card{padding:13px;border:1px solid var(--line);border-radius:12px}.confidence-card>div:first-child{display:flex;justify-content:space-between;gap:8px}.confidence-card strong{font-size:25px}.bar{height:5px;background:var(--soft);border-radius:99px;overflow:hidden;margin-top:8px}.bar i{display:block;height:100%;background:currentColor}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px}table{width:100%;border-collapse:collapse;min-width:760px}th{position:sticky;top:0;background:var(--soft);font-size:10px;text-transform:uppercase;letter-spacing:.075em;color:var(--muted)}th,td{padding:9px 11px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}tbody tr:hover{background:var(--soft)}.empty{padding:20px;color:var(--muted);border:1px dashed var(--line);border-radius:12px}.filter{width:100%;padding:9px 11px;border-radius:10px;border:1px solid var(--line);background:var(--panel);color:var(--ink);margin-bottom:8px}.graph{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.graph svg{display:block;width:100%;min-width:760px;max-height:540px}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;white-space:pre-wrap;word-break:break-word;background:var(--soft);border-radius:12px;padding:13px;max-height:430px;overflow:auto}.export-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.export-item{padding:14px;border:1px solid var(--line);border-radius:12px}.export-item button{width:100%;margin-top:8px}footer{margin-top:48px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}@media(max-width:980px){.hero,.grid-2,.grid-3,.confidence-grid,.export-grid{grid-template-columns:1fr}h1{font-size:34px}}@media print{.topbar,.filter,.export-actions{display:none!important}body{background:#fff;color:#000}.shell{max-width:none;padding:0}.card,.metric{box-shadow:none;break-inside:avoid}.table-wrap{overflow:visible}table{min-width:0;font-size:9px}.graph svg{min-width:0}}
"""
    nav_html=''.join(f'<a href="#{a}">{b}</a>' for a,b in nav)
    doc=f"""<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{esc(title)}</title><style>{css}</style></head><body><div class='shell'>
<div class='topbar'><div class='brand'>{logo_svg(34)}<div><strong>{BRAND_NAME}</strong><small>{BRAND_TAGLINE}</small></div></div><nav class='nav'>{nav_html}</nav><button class='btn' onclick='toggleTheme()'>◐ Tema</button><button class='btn' onclick='window.print()'>↧ PDF</button></div>
<header class='hero'><div><div class='eyebrow'>Investigation Station · {esc(case_id)}</div><h1>{esc(judgment or title)}</h1><div class='lede'>{esc(implication)}</div><p class='muted'>Analista: {esc(analyst)} · Gerado em {esc(generated)}</p></div><div class='hero-meta'>{_metric('P1 Actions',p1_n,'ações prioritárias')}{_metric('Block Ready',block_n,'IOCs')}{_metric('Hunt Ready',hunt_n,'IOCs')}{_metric('High Attribution',high_attr,'relações')}</div></header>
<section id='overview'><div class='section-head'><div><div class='eyebrow'>01 · Assessment</div><h2>Visão executiva</h2></div><p>O relatório começa pela decisão, não pela quantidade de JSON coletado.</p></div><div class='grid grid-2'><div class='card'><h3>Campaign State</h3><div class='judgment'>{esc(lifecycle.get('stage','UNKNOWN'))}</div><p class='muted'>{esc(lifecycle.get('reason',''))}</p></div><div class='card'><h3>Objective</h3><div class='judgment'>{esc(objectives.get('primary','unknown'))}</div><p class='muted'>Confiança: {esc(objectives.get('confidence',''))}</p></div><div class='card'><h3>Victimology</h3>{_table([victimology])}</div><div class='card'><h3>Confidence Matrix</h3><div class='confidence-grid'>{_confidence_cards(confidence)}</div></div></div></section>
<section id='actions'><div class='section-head'><div><div class='eyebrow'>02 · Decision</div><h2>Action Matrix</h2></div><p>O que fazer, quem deve fazer e por quê.</p></div><input class='filter' placeholder='Filtrar ações…' oninput="filterTable('actions-table',this.value)"><div class='card'>{_table(actions,table_id='actions-table')}</div></section>
<section id='iocs'><div class='section-head'><div><div class='eyebrow'>03 · IOC Quality</div><h2>IOC Decision Objects</h2></div><p>Confiança, atividade, actionability e risco de falso positivo permanecem separados.</p></div><input class='filter' placeholder='Filtrar IOC…' oninput="filterTable('ioc-table',this.value)"><div class='card'>{_ioc_decisions(iocs)}</div></section>
<section id='relationships'><div class='section-head'><div><div class='eyebrow'>04 · Graph Intelligence</div><h2>Relationship Graph</h2></div><p>Relações tipadas e ponderadas. Infraestrutura comum não pode virar ponte universal.</p></div>{relationship_svg(graph)}<div class='grid grid-2' style='margin-top:12px'><div class='card'><h3>Source independence</h3>{_table(source_ind)}</div><div class='card'><h3>Durable identifiers</h3>{_table(durable[:100])}</div></div></section>
<section id='similarity'><div class='section-head'><div><div class='eyebrow'>05 · Similarity</div><h2>Domain & Kit Similarity</h2></div><p>Similaridade produz candidatos e relações, nunca um veredito automático.</p></div><div class='grid grid-2'><div class='card'><h3>Domain similarity</h3>{_table(similarity[:200],table_id='similarity-table')}</div><div class='card'><h3>Negative evidence</h3>{_table(negative)}</div></div></section>
<section id='campaign'><div class='section-head'><div><div class='eyebrow'>06 · Campaign</div><h2>Campanha, timeline e churn</h2></div><p>Entender estratégia operacional exige tempo e mudança de infraestrutura, não apenas fotografia atual.</p></div>{timeline_svg(timeline)}<div class='grid grid-3' style='margin-top:12px'><div class='card'><h3>Clusters</h3>{_table(clusters)}</div><div class='card'><h3>Ownership</h3>{_table(ownership_rows)}</div><div class='card'><h3>Infrastructure churn</h3>{_table([churn])}</div></div></section>
<section id='attribution'><div class='section-head'><div><div class='eyebrow'>07 · Attribution</div><h2>Operator correlation & hypotheses</h2></div><p>Campanha, operador e identidade real são camadas analíticas diferentes.</p></div><div class='card'>{_table(attribution,table_id='attr-table')}</div><div class='card' style='margin-top:12px'><h3>Passive takeover exposure</h3>{_table(takeover)}</div></section>
<section id='ai'><div class='section-head'><div><div class='eyebrow'>08 · AI Assist</div><h2>GLiNER + Qwen</h2></div><p>Conteúdo derivado por IA. Não altera o Evidence Ledger e exige validação do analista.</p></div><div class='grid grid-2'><div class='card'><h3>AI Executive Summary</h3><div class='judgment'>{esc(ai_analysis.get('executive_summary','AI analysis not executed.'))}</div><div class='code'>{esc(json.dumps(ai_metadata,ensure_ascii=False,indent=2,default=str))}</div></div><div class='card'><h3>GLiNER entity candidates</h3>{_table(ai_entities[:150])}</div><div class='card'><h3>Key findings</h3>{_table(ai_analysis.get('key_findings',[]))}</div><div class='card'><h3>Competing hypotheses</h3>{_table(ai_analysis.get('hypotheses',[]))}</div><div class='card'><h3>AI collection priorities</h3>{_table(ai_analysis.get('collection_priorities',[]))}</div><div class='card'><h3>Caveats / validation</h3><div class='code'>{esc(json.dumps({'caveats':ai_analysis.get('caveats',[]),'validation':ai_analysis.get('_validation',{})},ensure_ascii=False,indent=2,default=str))}</div></div></div></section>
<section id='collection'><div class='section-head'><div><div class='eyebrow'>08 · Collection</div><h2>Gaps, pivôs e provider plan</h2></div><p>O próximo passo é priorizado pelo valor de informação, não pela vontade de consultar todas as APIs conhecidas pela humanidade.</p></div><div class='grid grid-3'><div class='card'><h3>Collection gaps</h3>{_table(gaps)}</div><div class='card'><h3>Next Best Pivots</h3>{_table(pivots[:60])}</div><div class='card'><h3>Provider plan</h3>{_table(provider_plan)}</div></div></section>
<section id='detection'><div class='section-head'><div><div class='eyebrow'>09 · Defense</div><h2>Detection Engineering</h2></div><p>Pacote candidato para DNS, proxy, e-mail, identidade e controles.</p></div><div class='card'><div class='code'>{esc(json.dumps(detection,ensure_ascii=False,indent=2,default=str))}</div></div></section>
<section id='evidence'><div class='section-head'><div><div class='eyebrow'>10 · Provenance</div><h2>Evidence Ledger</h2></div><p>Quem afirmou o quê, quando, por qual método e com qual confiabilidade.</p></div><input class='filter' placeholder='Filtrar evidência…' oninput="filterTable('evidence-table',this.value)"><div class='card'>{_table(evidence,table_id='evidence-table')}</div></section>
<section id='sources'><div class='section-head'><div><div class='eyebrow'>11 · Health</div><h2>Fontes e cobertura</h2></div><p>SKIPPED, UNAVAILABLE e falhas de coleta permanecem visíveis.</p></div><div class='grid grid-2'><div class='card'><h3>Source status</h3>{_table(source_status)}</div><div class='card'><h3>Feature coverage</h3>{_table(feature_matrix)}</div></div></section>
<section id='exports'><div class='section-head'><div><div class='eyebrow'>12 · Output</div><h2>Export Center</h2></div><p>Exporte somente o necessário para SOC, CTI, gestão ou preservação do caso.</p></div><div class='export-grid export-actions'><div class='export-item'><strong>Executive Brief</strong><button class='btn' onclick="downloadJSON('executive_brief')">JSON</button></div><div class='export-item'><strong>IOC Decisions</strong><button class='btn' onclick="downloadCSV('ioc_decisions')">CSV</button></div><div class='export-item'><strong>Actions</strong><button class='btn' onclick="downloadCSV('action_matrix')">CSV</button></div><div class='export-item'><strong>Evidence</strong><button class='btn' onclick="downloadCSV('evidence_ledger')">CSV</button></div><div class='export-item'><strong>Attribution</strong><button class='btn' onclick="downloadCSV('attribution_assessments')">CSV</button></div><div class='export-item'><strong>Similarity</strong><button class='btn' onclick="downloadCSV('domain_similarity')">CSV</button></div><div class='export-item'><strong>Full Case</strong><button class='btn' onclick='downloadAll()'>JSON</button></div><div class='export-item'><strong>PDF</strong><button class='btn' onclick='window.print()'>Print / PDF</button></div></div></section>
<footer>{logo_svg(24)} <strong>{BRAND_NAME}</strong> · Investigation Station 4.2 · {esc(case_id)}<br>Correlação não é identidade. Ausência de evidência não é evidência de ausência.</footer></div><script id='tropeiro-data' type='application/json'>{embedded}</script><script>
const D=JSON.parse(document.getElementById('tropeiro-data').textContent);function toggleTheme(){{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'':'dark';}}function filterTable(id,q){{q=q.toLowerCase();document.querySelectorAll('#'+id+' tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none');}}function saveBlob(name,text,type){{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{{type}}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}}function downloadJSON(key){{saveBlob('{esc(case_id)}_'+key+'.json',JSON.stringify(D[key]??{{}},null,2),'application/json');}}function csvEscape(v){{v=(v===null||v===undefined)?'':(typeof v==='object'?JSON.stringify(v):String(v));return '"'+v.replaceAll('"','""')+'"';}}function toCSV(rows){{if(!Array.isArray(rows))rows=[rows];if(!rows.length)return '';const cols=[...new Set(rows.flatMap(x=>Object.keys(x||{{}})))];return cols.map(csvEscape).join(',')+'\\n'+rows.map(r=>cols.map(c=>csvEscape((r||{{}})[c])).join(',')).join('\\n');}}function downloadCSV(key){{saveBlob('{esc(case_id)}_'+key+'.csv',toCSV(D[key]??[]),'text/csv;charset=utf-8');}}function downloadAll(){{saveBlob('{esc(case_id)}_tropeiro_case.json',JSON.stringify(D,null,2),'application/json');}}
</script></body></html>"""
    output_path.write_text(doc,encoding='utf-8');return output_path

def open_local_report(path):
    p=Path(path).resolve()
    try:webbrowser.open(p.as_uri());return True
    except Exception:return False
